// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.agenticimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Agentic executor. * * Executes a single [AgenticStep] and returns the [AgenticStepResult]. * * ## Step Types * *   - [AgenticStep.ToolCall] → look up tool in [AgenticToolRegistry], *     validate params, call [AgenticTool.execute] *   - [AgenticStep.LlmQuery] → call the LLM (local or cloud via *     [LlmCaller]) with the prompt *   - [AgenticStep.FinalAnswer] → no execution, just wrap in *     [AgenticStepResult.FinalAnswerProduced] * * ## Error Handling * *   - Tool not found → [AgenticStepResult.ToolFailure] (non-retryable) *   - Param validation failed → [AgenticStepResult.ToolFailure] (non-retryable) *   - Tool threw exception → [AgenticStepResult.ToolFailure] (retryable) *   - LLM call failed → [AgenticStepResult.LlmFailure] (retryable) *   - LLM timed out → [AgenticStepResult.LlmFailure] (retryable) * * The [AgenticCritic] decides whether to retry based on the `retryable` flag. * * ## Cost Tracking * *   - Tool calls: cost is 0 (tools are free; their internal costs are tracked *     separately by [com.roshan.persona.brain.llm.cost.LlmCostTracker]) *   - LLM queries: cost is computed by the LLM caller and returned in *     [AgenticStepResult.LlmSuccess.costUsd] * * @see <a href="docs/spec/module2-spec-review.pdf">§9.2 Executor</a> */@Singletonclass AgenticExecutor @Inject constructor(    private val toolRegistry: AgenticToolRegistry,    private val llmCaller: LlmCaller?,) {    /**     * Execute a single [step].     *     * @param step the step to execute     * @param context the brain context     * @return the result of execution     */    suspend fun execute(        step: AgenticStep,        context: BrainContext,    ): AgenticStepResult {        val startNanos = System.nanoTime()        return when (step) {            is AgenticStep.ToolCall -> executeToolCall(step, context, startNanos)            is AgenticStep.LlmQuery -> executeLlmQuery(step, context, startNanos)            is AgenticStep.FinalAnswer -> {                AgenticStepResult.FinalAnswerProduced(                    answer = step.answer,                    correlationId = context.correlationId,                    durationMs = 0L,                    costUsd = 0f,                )            }        }    }    /**     * Execute a tool call.     */    private suspend fun executeToolCall(        step: AgenticStep.ToolCall,        context: BrainContext,        startNanos: Long,    ): AgenticStepResult {        val correlationId = context.correlationId        // Look up tool        val tool = toolRegistry.getById(step.toolId)        if (tool == null) {            return AgenticStepResult.ToolFailure(                toolId = step.toolId,                error = "Unknown tool: ${step.toolId}",                retryable = false,                correlationId = correlationId,                durationMs = durationMs(startNanos),            )        }        // Validate params        val validationError = toolRegistry.validateParams(step.toolId, step.params)        if (validationError != null) {            return AgenticStepResult.ToolFailure(                toolId = step.toolId,                error = validationError,                retryable = false,                correlationId = correlationId,                durationMs = durationMs(startNanos),            )        }        // Check network requirement        if (tool.requiresNetwork && !context.deviceContext.isOnline) {            return AgenticStepResult.ToolFailure(                toolId = step.toolId,                error = "Tool requires network but device is offline",                retryable = false,                correlationId = correlationId,                durationMs = durationMs(startNanos),            )        }        // Execute        return try {            val result = tool.execute(step.params, context)            Timber.tag("NOUS.L5").v(                "Tool %s executed in %dms",                step.toolId,                when (result) {                    is AgenticStepResult.ToolSuccess -> result.durationMs                    is AgenticStepResult.ToolFailure -> result.durationMs                    else -> 0L                },            )            result        } catch (t: Throwable) {            Timber.tag("NOUS.L5").w(t, "Tool %s threw exception", step.toolId)            AgenticStepResult.ToolFailure(                toolId = step.toolId,                error = "Tool crashed: ${t.message ?: t::class.simpleName}",                retryable = true,                correlationId = correlationId,                durationMs = durationMs(startNanos),            )        }    }    /**     * Execute an LLM query.     */    private suspend fun executeLlmQuery(        step: AgenticStep.LlmQuery,        context: BrainContext,        startNanos: Long,    ): AgenticStepResult {        val correlationId = context.correlationId        if (llmCaller == null) {            return AgenticStepResult.LlmFailure(                error = "No LLM available for agentic query",                retryable = false,                correlationId = correlationId,                durationMs = durationMs(startNanos),            )        }        return try {            when (val result = llmCaller.invoke(step.prompt, context)) {                is Result.Success -> AgenticStepResult.LlmSuccess(                    text = result.data,                    tokensUsed = 0,  // populated by real LLM caller in Module 4                    correlationId = correlationId,                    durationMs = durationMs(startNanos),                    costUsd = 0f,  // populated by real LLM caller                )                is Result.Partial -> AgenticStepResult.LlmSuccess(                    text = result.data,                    tokensUsed = 0,                    correlationId = correlationId,                    durationMs = durationMs(startNanos),                    costUsd = 0f,                )                is Result.Failure -> AgenticStepResult.LlmFailure(                    error = result.error.message,                    retryable = result.error.retryable,                    correlationId = correlationId,                    durationMs = durationMs(startNanos),                )            }        } catch (t: Throwable) {            AgenticStepResult.LlmFailure(                error = "LLM query crashed: ${t.message ?: t::class.simpleName}",                retryable = true,                correlationId = correlationId,                durationMs = durationMs(startNanos),            )        }    }    private fun durationMs(startNanos: Long): Long =        (System.nanoTime() - startNanos) / 1_000_000}/** * Functional interface for calling the LLM (used by [AgenticExecutor]). * * Real implementation wires to [com.roshan.persona.brain.llm.router.HybridLlmRouter] * in Module 9. For Module 2 tests, use a fake that returns predetermined text. */fun interface LlmCaller {    suspend fun invoke(prompt: String, context: BrainContext): Result<String>}